# Chat Media Components

Based on the request to use new media components for chat media files, I'll create a comprehensive media handling system with specialized components.

```vue src/components/chat/ChatMediaContainer.vue
<script setup>
import ChatMediaImage from './media/ChatMediaImage.vue'
import ChatMediaVideo from './media/ChatMediaVideo.vue'
import ChatMediaAudio from './media/ChatMediaAudio.vue'
import ChatMediaFile from './media/ChatMediaFile.vue'
import ChatMediaGallery from './media/ChatMediaGallery.vue'
</script>

<template>
  <div class="w-full flex flex-col gap-2">
    <!-- Image Gallery -->
    <ChatMediaGallery
      v-if="images.length"
      :images="images"
      @select="$emit('select-media', $event)"
      @remove="$emit('remove-media', $event)"
    />

    <!-- Video Files -->
    <div v-if="videos.length" class="flex flex-col gap-2">
      <ChatMediaVideo
        v-for="video in videos"
        :key="video.src"
        :video="video"
        @remove="$emit('remove-media', $event)"
      />
    </div>

    <!-- Audio Files -->
    <div v-if="audios.length" class="flex flex-col gap-2">
      <ChatMediaAudio
        v-for="audio in audios"
        :key="audio.src"
        :audio="audio"
        @remove="$emit('remove-media', $event)"
      />
    </div>

    <!-- Other Files -->
    <div v-if="files.length" class="flex flex-col gap-2">
      <ChatMediaFile
        v-for="file in files"
        :key="file"
        :file="file"
        @remove="$emit('remove-media', $event)"
        @preview="$emit('preview-media', $event)"
      />
    </div>
  </div>
</template>

<script>
export default {
  props: {
    media: {
      type: Array,
      default: () => []
    },
    chatFiles: {
      type: Array,
      default: () => []
    }
  },
  emits: ['select-media', 'remove-media', 'preview-media'],
  computed: {
    images() {
      return this.media.filter(m => m.type === 'image' || this.isImageFile(m))
    },
    videos() {
      return this.media.filter(m => m.type === 'video' || this.isVideoFile(m))
    },
    audios() {
      return this.media.filter(m => m.type === 'audio' || this.isAudioFile(m))
    },
    files() {
      return this.chatFiles.filter(f => !this.isImageFile(f) && !this.isVideoFile(f) && !this.isAudioFile(f))
    }
  },
  methods: {
    isImageFile(file) {
      const imageExts = ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.svg']
      return imageExts.some(ext => file.toLowerCase().endsWith(ext))
    },
    isVideoFile(file) {
      const videoExts = ['.mp4', '.webm', '.ogg', '.mov', '.avi']
      return videoExts.some(ext => file.toLowerCase().endsWith(ext))
    },
    isAudioFile(file) {
      const audioExts = ['.mp3', '.wav', '.ogg', '.m4a', '.flac']
      return audioExts.some(ext => file.toLowerCase().endsWith(ext))
    }
  }
}
</script>
```

