```vue src/components/chat/media/ChatMediaVideo.vue
<script setup>
</script>

<template>
  <div class="card bg-base-200 shadow-sm">
    <div class="card-body p-3">
      <div class="flex items-start gap-2">
        <div class="flex-1 min-w-0">
          <video
            :src="video.src || video"
            class="w-full max-h-64 rounded-lg bg-black"
            controls
            preload="metadata"
          />
          <div class="mt-2 flex gap-2 items-center">
            <i class="fa-solid fa-video text-primary"></i>
            <span class="text-sm font-medium truncate">
              {{ getFileName(video) }}
            </span>
            <span class="text-xs text-base-content/60 ml-auto">
              {{ getMediaSize(video) }}
            </span>
          </div>
        </div>
        <button
          class="btn btn-xs btn-ghost"
          @click="$emit('remove', video)"
          title="Remove video"
        >
          <i class="fa-solid fa-trash"></i>
        </button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    video: {
      type: [Object, String],
      required: true
    }
  },
  emits: ['remove'],
  methods: {
    getFileName(video) {
      const src = typeof video === 'string' ? video : video.src
      return src.split('/').pop()
    },
    getMediaSize(video) {
      if (typeof video === 'object' && video.size) {
        return this.formatBytes(video.size)
      }
      return ''
    },
    formatBytes(bytes) {
      if (bytes === 0) return '0 Bytes'
      const k = 1024
      const sizes = ['Bytes', 'KB', 'MB', 'GB']
      const i = Math.floor(Math.log(bytes) / Math.log(k))
      return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i]
    }
  }
}
</script>
