        <button class="btn btn-ghost" @click="$emit('close')">
          Close
        </button>
      </div>
    </div>
    <div class="modal-backdrop" @click="$emit('close')"></div>
  </div>
</template>

<script>
export default {
  props: {
    media: {
      type: [Object, String],
      default: null
    }
  },
  emits: ['close'],
  computed: {
    mediaSrc() {
      return typeof this.media === 'string' ? this.media : this.media?.src || this.media
    },
    isImage() {
      return ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.svg'].some(
        ext => this.mediaSrc?.toLowerCase().endsWith(ext)
      )
    },
    isVideo() {
      return ['.mp4', '.webm', '.ogg', '.mov', '.avi'].some(
        ext => this.mediaSrc?.toLowerCase().endsWith(ext)
      )
    },
    isAudio() {
      return ['.mp3', '.wav', '.ogg', '.m4a', '.flac'].some(
        ext => this.mediaSrc?.toLowerCase().endsWith(ext)
      )
    }
  },
  methods: {
    getFileName(file) {
      return file?.split('/').pop() || 'File'
    }
  }
}
</script>
